function chime(ctx) {
	const now = ctx.currentTime;
	[
		660,
		990,
		1320
	].forEach((freq, i) => {
		const osc = ctx.createOscillator();
		const gain = ctx.createGain();
		osc.frequency.value = freq;
		gain.gain.setValueAtTime(1e-4, now + i * .16);
		gain.gain.exponentialRampToValueAtTime(.3, now + i * .16 + .02);
		gain.gain.exponentialRampToValueAtTime(1e-4, now + i * .16 + .22);
		osc.connect(gain).connect(ctx.destination);
		osc.start(now + i * .16);
		osc.stop(now + i * .16 + .26);
	});
}
